import{_ as e,o as a,c as r,ae as l}from"./chunks/framework.DCJ5T8RY.js";const b=JSON.parse('{"title":"HTTP缓存小结","description":"","frontmatter":{"title":"HTTP缓存小结","date":"2020-02-25"},"headers":[],"relativePath":"2020/http-caching-summary.md","filePath":"2020/http-caching-summary.md","lastUpdated":1786185344000}'),d={name:"2020/http-caching-summary.md"};function o(c,t,i,h,n,s){return a(),r("div",null,[...t[0]||(t[0]=[l('<h3 id="常见相关http-header" tabindex="-1">常见相关HTTP Header <a class="header-anchor" href="#常见相关http-header" aria-label="Permalink to &quot;常见相关HTTP Header&quot;">​</a></h3><h4 id="http-1-0" tabindex="-1">HTTP 1.0 <a class="header-anchor" href="#http-1-0" aria-label="Permalink to &quot;HTTP 1.0&quot;">​</a></h4><ul><li><code>Pragma</code><br> 与HTTP 1.1 <code>Cache-Control</code>对等，为了兼容而存在；<br> 如果<code>Cache-Control</code>同时存在，Pragma会被忽略；<br> 通常设置为<code>Pragma: no-cache</code>;</li></ul><h4 id="http-1-1-cache-control" tabindex="-1">HTTP 1.1 Cache-Control <a class="header-anchor" href="#http-1-1-cache-control" aria-label="Permalink to &quot;HTTP 1.1 Cache-Control&quot;">​</a></h4><p>HTTP 1.1引入请求头，用于控制缓存策略</p><table tabindex="0"><thead><tr><th style="text-align:right;">HTTP header</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:right;"><code>public</code></td><td style="text-align:left;">都可以缓存</td></tr><tr><td style="text-align:right;"><code>private</code></td><td style="text-align:left;">必须保存在私有缓存中，不可保存在共享缓存，即不可保存在CDN节点</td></tr><tr><td style="text-align:right;"><code>no-cache</code></td><td style="text-align:left;">保存缓存文件到磁盘，但未与源服务器验证前，不可使用</td></tr><tr><td style="text-align:right;"><code>no-store</code></td><td style="text-align:left;">1.不保存缓存文件到磁盘，但可以保存到内存中，转发后会尽快删除；<br>2. 无法保证私密性；</td></tr><tr><td style="text-align:right;"><code>must-revalidate</code></td><td style="text-align:left;">仅针对过期缓存，在未与源服务器验证前，不可使用</td></tr><tr><td style="text-align:right;"><code>max-stale</code></td><td style="text-align:left;">1. 请求头，表示愿意接受设置的过期时间内的缓存；<br>2. <code>max-stale: 60</code>表示过期60秒内的缓存，客户端也可以接受</td></tr></tbody></table><blockquote><p><strong>注意<code>must-revalidate</code>与<code>no-cache</code>差别</strong></p><ul><li>前者只要求验证已过期缓存</li><li>后者不论缓存是否过期都需要验证；</li></ul></blockquote><h3 id="缓存类别" tabindex="-1">缓存类别 <a class="header-anchor" href="#缓存类别" aria-label="Permalink to &quot;缓存类别&quot;">​</a></h3><h4 id="强缓存" tabindex="-1">强缓存 <a class="header-anchor" href="#强缓存" aria-label="Permalink to &quot;强缓存&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:right;">HTTP header</th><th style="text-align:center;">所属标准</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Expires</code></td><td style="text-align:center;">HTTP 1.0</td><td style="text-align:left;">1.HTTP日期时间戳<br>2. 优先级低于<code>Cache-Control: max-age</code>，如果后者出现<code>Expires</code>将被忽略<br>3.客户端本地时间会影响时间判定<br>4. 如果解析时间错误或时间格式错误，缓存将被认为已过期</td></tr><tr><td style="text-align:right;"><code>Cache-Control: max-age</code></td><td style="text-align:center;">HTTP 1.1</td><td style="text-align:left;">1.表示缓存最大有效期，单位是秒<br>2.优先级高于<code>Expires</code></td></tr><tr><td style="text-align:right;"><code>Cache-Control: s-maxage</code></td><td style="text-align:center;">HTTP 1.1</td><td style="text-align:left;">1.和<code>max-age</code>类似，但用于控制共享缓存，即CDN的最大缓存有效期<br>2.优先级高于<code>max-age</code>和<code>Expires</code></td></tr></tbody></table><blockquote><p>强缓存命中，返回HTTP状态码200</p></blockquote><h4 id="协商缓存" tabindex="-1">协商缓存 <a class="header-anchor" href="#协商缓存" aria-label="Permalink to &quot;协商缓存&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:right;">HTTP header</th><th style="text-align:center;">所属标准</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:right;">请求头：<code>If-Modified-since</code><br>响应头：<code>Last-Modified</code></td><td style="text-align:center;">HTTP 1.0</td><td style="text-align:left;">1.HTTP日期时间戳<br>2. 优先级低于<code>Etag</code>，如果后者出现将被忽略<br>3.只能精确到秒，速度快于1秒的变化无法感知<br>4. 连续变化但最后内容未变，会导致频繁刷新更新时间，导致之前的缓存失效</td></tr><tr><td style="text-align:right;">请求头: <code>If-None-Match</code><br>响应头: <code>Etag</code></td><td style="text-align:center;">HTTP 1.1</td><td style="text-align:left;">1.表示文件指纹，变化只与文件内容有关<br>2.优先级高于<code>Last-Modified</code><br>3.Etag生成与具体算法有关，分布式系统中每台机器可能会为相同文件生成不同的Etag，需要统一计算规则</td></tr></tbody></table><blockquote><p>协商缓存命中返回HTTP状态码304，未命中会重新请求，成功返回200</p></blockquote><h3 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h3><h4 id="静态文件" tabindex="-1">静态文件 <a class="header-anchor" href="#静态文件" aria-label="Permalink to &quot;静态文件&quot;">​</a></h4><p>变化较少的静态资源文件，如图片，或变化频繁但每个版本相对独立的静态资源文件，如js,css文件，尽量强缓存，并设置长有效期，通过hash或者类似方法区分不同文件版本，可以减少资源请求</p><h4 id="html文件" tabindex="-1">html文件 <a class="header-anchor" href="#html文件" aria-label="Permalink to &quot;html文件&quot;">​</a></h4><p>一般设置为<code>Cache-Control: no-cache</code>，要求每次回源验证，以确保每次用户访问到的都是最新版本的App；但并不绝对，有些时效性没那么强的内容，或者内容相对稳定、或者需要通过缓存减少服务器访问压力的场景，也可以结合使用<code>Cache-Control: max-age=xxx</code></p><ul><li>前者例子见参考文献3</li><li>后者例子可见各类新闻网站，常见设置为<code>max-age=60</code><br> 因为新闻内容相对稳定，设置强缓存影响css和js文件的更新，并不影响内容阅读，用户感知不明显，且此设置有助于减少服务器访问压力</li><li>缺点：结合<code>max-age</code>的网站，通常会有多个版本同时运行在线上，比较难以定位线上问题</li></ul><h3 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h3><p>[1] <a href="https://tools.ietf.org/html/rfc7234" target="_blank" rel="noreferrer">RFC 7324</a><br> [2] <a href="https://tools.ietf.org/html/rfc7232" target="_blank" rel="noreferrer">RFC 7232</a><br> [3] <a href="https://jakearchibald.com/2016/caching-best-practices/" target="_blank" rel="noreferrer">Jake·Archibald: caching-best-practices</a></p>',22)])])}const x=e(d,[["render",o]]);export{b as __pageData,x as default};
